import { Page, expect, test } from '@playwright/test';
import * as path from 'path';
import '../../shared/config/env';

/**
 * Support for specs against the real Rosabon Admin Portal (dev).
 * Selectors follow the CURRENT UI (see reports/ui-inspect, regenerated by scripts/inspect-admin-*.js),
 * not the original codegen recording. Credentials come from .env (DEV_ADMIN_*).
 *
 * UI facts these helpers encode:
 *  - Hash routing (#/…); landing page after login is Pending Approvals.
 *  - Detail pages (Customer 360, investment detail) render outside the <main> landmark.
 *  - Modals are not exposed as role="dialog" and survive hash-only navigation → open() reloads.
 *  - State filter buttons carry counts ("Pending approval 3") → stateButton() matches by prefix.
 */
export const DEV = {
  url: process.env.DEV_ADMIN_URL ?? 'https://rosabon-app-admin-dev.rosabon-finance.com',
  email: process.env.DEV_ADMIN_EMAIL ?? '',
  password: process.env.DEV_ADMIN_PASSWORD ?? '',
  destructive: process.env.DEV_ALLOW_DESTRUCTIVE === '1',
  storageState: path.resolve(__dirname, '../../.auth/dev-super-admin.json'),
};

export const ROUTES = {
  customers: '#/customer/directory',
  investments: '#/investment-management',
  approvalQueue: '#/investment-management/approval-queue',
  requests: '#/investment-management/requests',
  breakRequests: '#/investment-management/break-requests',
  withdrawals: '#/investment-management/withdrawal-requests',
  topUps: '#/investment-management/top-up-requests',
  rollovers: '#/investment-management/rollover-requests',
  unlocks: '#/investment-management/unlock-requests',
  systemAlerts: '#/investment-management/system-alerts',
  autoRollover: '#/investment-management/auto-rollover',
  statutoryTax: '#/investment-management/statutory-rate-propagations',
  loanApplications: '#/loan-management/applications',
  loanRepayments: '#/loan-management/repayments',
  payroll: '#/loan-management/payroll',
  walletBoard: '#/wallet/board',
  ledger: '#/ledger/monitor',
  campaigns: '#/operations/communications/campaigns',
  banners: '#/operations/communications/discovery-banners',
  products: '#/configurations/product-management',
  loanPurposes: '#/loan-products/purposes',
  loanVariants: '#/loan-products/variants',
  preEligibility: '#/loan-products/pre-eligibility',
  penaltyLadders: '#/investment-products/penalty-ladders',
  investmentTax: '#/investment-products/tax',
  rateFees: '#/rates/fees',
  approvalThreshold: '#/loan-approvals',
  corridors: '#/corridors/list',
  documentSetup: '#/configurations/product-management/document-setup',
  pendingApprovals: '#/rbac/approvals',
  auditLog: '#/reporting/audit',
} as const;

/**
 * Pages switched off in the 3 November 2026 update: marked "COMING SOON" in the menu or removed from it.
 * They now redirect to Pending Approvals or render only their title, so checks on them are skipped (not failed).
 */
export const REMOVED_ON_3_NOV = [
  ROUTES.approvalQueue, ROUTES.requests, ROUTES.breakRequests, ROUTES.withdrawals, ROUTES.topUps, ROUTES.rollovers,
  ROUTES.unlocks, ROUTES.autoRollover, ROUTES.statutoryTax, ROUTES.payroll, ROUTES.walletBoard, ROUTES.ledger,
  ROUTES.banners, '#/coming-soon/support', '#/rewards/rules', '#/reports-and-analytics/dashboards', '#/classifications',
  '#/vocabularies', '#/settings/admin-action-thresholds', '#/settings/communications-providers', '#/settings/metric-definitions',
] as readonly string[];

/** In-page links removed in the same update (Customer Management sub-pages). */
export const REMOVED_LINKS_ON_3_NOV = ['Review Queues', 'Auto Grants', 'Screening', 'Account Controls'] as readonly string[];

const REMOVED_REASON = 'No longer in the portal: switched off ("Coming soon" or removed from the menu) in the 3 November update';

/** Unique, human-readable suffix so re-runs never collide with data from earlier runs. */
/** Some name fields reject digits ("must contain only allowed characters"), so the suffix is letters only. */
export const uniq = (prefix: string) =>
  `${prefix} ${Date.now().toString(26).split('').map((c) => String.fromCharCode((parseInt(c, 26) % 26) + 97)).join('').slice(-7)}`;

export function destructive(): void {
  test.skip(!DEV.destructive, 'Acts on existing records by position — set DEV_ALLOW_DESTRUCTIVE=1 to run');
}

/** Opens a route with a full reload (clears any modal left open by hash-only navigation). */
export async function open(page: Page, route: string): Promise<void> {
  test.skip(REMOVED_ON_3_NOV.includes(route), REMOVED_REASON);
  await page.goto(`/${route}`);
  await page.reload();
  await page.waitForLoadState('networkidle', { timeout: 20_000 }).catch(() => undefined);
  await expect(page).not.toHaveURL(/#\/login/);
}

export async function subNav(page: Page, link: string): Promise<void> {
  test.skip(REMOVED_LINKS_ON_3_NOV.includes(link), REMOVED_REASON);
  await page.getByRole('link', { name: link, exact: true }).first().click();
  await page.waitForLoadState('networkidle', { timeout: 20_000 }).catch(() => undefined);
}

export function btn(page: Page, name: string | RegExp) {
  return page.getByRole('button', { name, exact: typeof name === 'string' });
}

/** State filter buttons show counts: "Pending approval 3". */
export function stateButton(page: Page, state: string) {
  return page.getByRole('button', { name: new RegExp(`^${state.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}( \\d+)?$`) });
}

export async function clickStates(page: Page, states: string[]): Promise<void> {
  for (const s of states) {
    await stateButton(page, s).click();
    await page.waitForLoadState('networkidle', { timeout: 15_000 }).catch(() => undefined);
    await expect(stateButton(page, s)).toBeVisible();
  }
}

export async function exportCsv(page: Page): Promise<void> {
  const [download] = await Promise.all([page.waitForEvent('download'), btn(page, 'Export CSV').click()]);
  expect(download.suggestedFilename()).toMatch(/\.csv$/i);
}

/** Evidence panel: Type combobox + reference + Add. */
export async function addEvidence(page: Page, type: string, reference: string): Promise<void> {
  await page.getByRole('combobox', { name: 'Type', exact: true }).selectOption(type);
  await page.getByRole('textbox', { name: /^Reference — ticket number/ }).fill(reference);
  await btn(page, 'Add').click();
}

/** Close the topmost modal/drawer. */
export async function closeModal(page: Page): Promise<void> {
  await page.getByRole('button', { name: 'Close', exact: true }).last().click();
}
